1136	+    do {                                                                       \
1137	+        if (!(condition)) {                                                    \
1138	+            dprintf(report_fd, "line %d: %s (errno=%d)\n", __LINE__,             \
1139	+                    #condition, errno);                                        \
1140	+            exit(1);                                                           \
1141	+        }                                                                      \
1142	+    } while (0)
