1144	+static int same_object(struct stat left, struct stat right) {
1145	+    return left.st_dev == right.st_dev && left.st_ino == right.st_ino;
1146	+}
1147	+
1148	+static void check_statx_identity(struct statx actual, struct stat expected) {
1149	+    CHECK((actual.stx_mask & (STATX_INO | STATX_TYPE)) ==
1150	+          (STATX_INO | STATX_TYPE));
1151	+    CHECK(actual.stx_ino == expected.st_ino);
1152	+    CHECK(actual.stx_dev_major == major(expected.st_dev));
1153	+    CHECK(actual.stx_dev_minor == minor(expected.st_dev));
1154	+    CHECK(((mode_t)actual.stx_mode & S_IFMT) == (expected.st_mode & S_IFMT));
1155	+}
