1157	+static void check_descriptor_stat_routes(int fd, struct stat expected) {
1158	+    const int flags[] = {AT_EMPTY_PATH, AT_EMPTY_PATH | AT_SYMLINK_NOFOLLOW};
1159	+    for (size_t i = 0; i < sizeof(flags) / sizeof(flags[0]); ++i) {
1160	+        struct stat actual;
1161	+        CHECK(syscall(SYS_newfstatat, fd, "", &actual, flags[i]) == 0);
1162	+        CHECK(same_object(actual, expected));
1163	+        struct statx extended;
1164	+        CHECK(syscall(SYS_statx, fd, "", flags[i], STATX_BASIC_STATS,
1165	+                      &extended) == 0);
1166	+        check_statx_identity(extended, expected);
1167	+    }
