40	fn decimal(field: &[u8]) -> Option<u64> {
41	    if field.is_empty() || field.iter().any(|byte| !byte.is_ascii_digit()) {
42	        return None;
43	    }
44	    std::str::from_utf8(field).ok()?.parse().ok()
